begin;
create temp table taxonomy_results(check_name text,passed boolean);
do $$
declare actor uuid;run_id uuid:=gen_random_uuid();ext text:='nhs:taxonomy-fixture-'||gen_random_uuid();candidate jsonb;details jsonb;result jsonb;row_data public.opportunities;denied boolean;before_count bigint;preview_id uuid:=gen_random_uuid();legacy_id uuid:=gen_random_uuid();
begin
 select user_id into actor from private_website_lab.member_roles where role='full_admin' and private_website_lab.permitted(user_id,'opportunities') limit 1;
 if actor is null then raise exception 'Approved staging Full admin fixture required';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.jwt.claims','{"role":"authenticated"}',true);
 details:='{"version":"mettelo-occupations-v9","eligible":true,"status":"high","score":92,"categories":["03","10","20"],"seniority":"senior","roleFamily":"BI Developer","scoreType":"rule-based relevance; not a probability"}'::jsonb;
 candidate:=jsonb_build_object('external_job_id',ext,'title','Senior NHS BI Developer · taxonomy rollback fixture','organisation','Synthetic NHS Trust','opportunity_type','job','summary','Synthetic SQL and Power BI fixture. No real vacancy.','source_url','https://www.jobs.nhs.uk/candidate/jobadvert/taxonomy-fixture','official_application_url','https://www.jobs.nhs.uk/candidate/jobadvert/taxonomy-fixture','closes_at',now()+interval '7 days','original_published_at',now(),'data_ai_relevance_score',92,'data_ai_relevance_status','high','role_family','BI Developer','role_category','Business Intelligence & Reporting','classification_version','mettelo-occupations-v9','classification_details',details,'source_organisation','NHS Jobs','country_code','GB');
 result:=public.website_publish_opportunity_batch(run_id,jsonb_build_array(candidate));
 if result->>'written'<>'1' then raise exception 'Fixture not written';end if;
 select * into row_data from public.opportunities where external_job_id=ext;
 if row_data.title<>candidate->>'title' or row_data.classification_details<>details or row_data.role_category<>'Business Intelligence & Reporting' then raise exception 'Structured metadata or original title lost';end if;
 insert into taxonomy_results values('Publication retains advertised title, multiple categories, seniority and evidence',true);
 result:=public.website_publish_opportunity_batch(run_id,jsonb_build_array(candidate));if result->>'written'<>'1' then raise exception 'Replay receipt changed';end if;
 denied:=false;begin perform public.website_publish_opportunity_batch(run_id,jsonb_build_array(candidate||'{"title":"Modified retry"}'));exception when invalid_parameter_value then denied:=true;end;
 if not denied then raise exception 'Changed replay payload accepted';end if;
 insert into taxonomy_results values('Exact replay is idempotent and changed payload is rejected',true);
 candidate:=candidate||jsonb_build_object('role_family','Updated BI family','role_category','Updated category','classification_details',details||'{"score":96}');
 perform public.website_publish_opportunity_batch(gen_random_uuid(),jsonb_build_array(candidate));
 select * into row_data from public.opportunities where external_job_id=ext;
 if row_data.role_family<>'Updated BI family' or row_data.role_category<>'Updated category' or row_data.classification_details->>'score'<>'96' then raise exception 'Classification refresh lost';end if;
 update public.opportunities set publication_mode='manual' where id=row_data.id;
 result:=public.website_publish_opportunity_batch(gen_random_uuid(),jsonb_build_array(candidate||'{"title":"Should stay protected"}'));
 if result->>'protected'<>'1' or (select title from public.opportunities where id=row_data.id)<>candidate->>'title' then raise exception 'Manual protection changed';end if;
 update public.opportunities set publication_mode='auto',status='archived' where id=row_data.id;
 result:=public.website_publish_opportunity_batch(gen_random_uuid(),jsonb_build_array(candidate));if result->>'protected'<>'1' then raise exception 'Archive protection changed';end if;
 insert into taxonomy_results values('Metadata refresh works; manual and archived jobs remain protected',true);
 result:=public.website_publish_opportunity_batch(gen_random_uuid(),jsonb_build_array(candidate||jsonb_build_object('external_job_id',ext||'-invalid','classification_details',details||'{"eligible":false}')));
 if result->>'rejected'<>'1' or result->>'written'<>'0' then raise exception 'Invalid classification published';end if;
 result:=public.website_publish_opportunity_batch(gen_random_uuid(),jsonb_build_array(candidate||jsonb_build_object('external_job_id',ext||'-review','data_ai_relevance_status','medium','data_ai_relevance_score',75)));
 if result->>'rejected'<>'1' then raise exception 'Review candidate published';end if;
 insert into taxonomy_results values('Review and incomplete classification candidates cannot enter automatic publication',true);
 result:=public.website_publish_opportunity_batch(gen_random_uuid(),jsonb_build_array(candidate||jsonb_build_object('external_job_id',ext||'-v8','classification_version','mettelo-occupations-v8','classification_details',details||'{"version":"mettelo-occupations-v8"}')));
 if result->>'rejected'<>'1' or result->>'written'<>'0' then raise exception 'Stale v8 candidate published';end if;
 insert into taxonomy_results values('Previous rules version is rejected even through direct service publication',true);
 select count(*) into before_count from public.opportunities;
 perform public.website_opportunity_admin('prepare',jsonb_build_object('runId',preview_id,'taxonomyVersion','mettelo-occupations-v9','candidates','[]'::jsonb,'reviewCandidates',jsonb_build_array(jsonb_build_object('title','Information Officer','classification_details','{"status":"medium","eligible":false}'::jsonb)),'sourceStats','[]'::jsonb));
 result:=public.website_opportunity_admin('list');
 if result#>>'{batch,taxonomyVersion}'<>'mettelo-occupations-v9' or jsonb_array_length(result#>'{batch,reviewCandidates}')<>1 or (select count(*) from public.opportunities)<>before_count then raise exception 'Preview leaked review candidate or lost review metadata';end if;
 insert into private_opportunity_pipeline.prepared_batches(id,owner_id,payload) values(legacy_id,actor,'{"candidates":[]}'::jsonb);
 denied:=false;begin perform public.website_opportunity_admin('publish',jsonb_build_object('runId',legacy_id));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Legacy preview published';end if;
 insert into taxonomy_results values('Admin preview exposes review-only list and refuses stale taxonomy publication',true);
 if has_function_privilege('anon','public.website_publish_opportunity_batch(uuid,jsonb)','execute') or has_function_privilege('authenticated','public.website_publish_opportunity_batch(uuid,jsonb)','execute') then raise exception 'Direct publication grant widened';end if;
 if has_table_privilege('anon','public.opportunities','update') or has_table_privilege('authenticated','private_opportunity_pipeline.prepared_batches','select') then raise exception 'Private/write permissions widened';end if;
 insert into taxonomy_results values('Existing public-read/private-write boundary unchanged',true);
end $$;
select * from taxonomy_results;
rollback;
